// Function to create and display the modal structure
function createModal() {
  // Create modal structure as a template string
  const modalHTML = `
  <style>
    #thanks-yous-try {
      display: none;
    }
    .custom-dropdown-item {
      color: black;
    }
    .subscribe-button-text {
      font-size: 20px;
      font-weight: 500;
      color: black;
    }
    #tryNowModalLabel {
      color: black;
    }
    .custom-dropdown-toggle {
      color: #8c8585;
    }
  </style>

  <div class="modal fade" id="tryNowModal" tabindex="-1" aria-labelledby="tryNowModalLabel" aria-hidden="true">
    <div class="modal-dialog">
      <div class="modal-content" id="trynowheader">
        <h5 class="modal-title" id="tryNowModalLabel">Thanks for your interest in exploring Apurva.ai INSIGHTS!</h5>
        <h5 class="modal-title" id="tryNowModalLabel">Please share the details below to get started</h5>
        <button type="button" id="closetry" class="close" data-dismiss="modal" aria-label="Close">
          <span aria-hidden="true">&times;</span>
        </button>
        <div class="modal-body">
          <form id="tryNowForm">
            <div class="sub-group">
              <input type="text" class="trynow-textbox" id="Names" name="Names" placeholder="Name" required style="color: black; display: block" />
              <p class="validation-message" id="name-validations" style="display: none; color: red">Name is required</p>
            </div>
            <div class="sub-group">
              <input type="email" class="trynow-textbox" id="Emails" name="Emails" placeholder="Email ID" required style="color: black" />
              <span class="validation-message" id="email-validations" style="display: none; color: red">Please enter a valid email address</span>
            </div>
            <div class="sub-group">
              <input type="text" class="trynow-textbox" id="Organisations" name="Organisations" placeholder="Name of the organisation" required style="color: black" />
              <span class="validation-message" id="org-validations" style="display: none; color: red">Organisation is required</span>
            </div>
            <div class="sub-group">
              <input type="text" class="trynow-textbox" id="Domain" name="Domain" placeholder="Area/domain of expertise" required style="color: black" />
              <span class="validation-message" id="domain-validation" style="display: none; color: red">Area/domain of expertise is required</span>
            </div>
            <div class="dropdown">
              <div class="custom-dropdown-toggle" id="CommunityReach" name="Community_Reach">
                <span>Community reach</span>
                <span class="dropdown-arrow"></span>
              </div>
              <div class="custom-dropdown-menu" id="customDropdownMenu">
                <button class="custom-dropdown-item" type="button">0-10000</button>
                <button class="custom-dropdown-item" type="button">10000-70000</button>
                <button class="custom-dropdown-item" type="button">70,000+</button>
                <button class="custom-dropdown-item" type="button">NA</button>
              </div>
            </div>
            <span class="validation-message" id="community-reach-validation" style="display: none; color: red;">Community reach is required</span>
            <input type="hidden" id="Community_Reach" name="Community_Reach" />
            <button type="submit" class="sub mx-auto d-block" type="button" id="TryNowButton">
              <div class="subscribe-button-text">Submit</div>
            </button>
            <div id="responseMessage"></div>
            <p class="thank-you-messages" id="thanks-yous-try" style="display: none;">Thank you! Our team will get back to you shortly.</p>
          </form>
        </div>
      </div>
    </div>
  </div>
  `;
  document.body.insertAdjacentHTML("beforeend", modalHTML);
  setupDropdown();
}

// Function to close side menu if open
function closeSideMenuIfOpen() {
  const sideMenu = document.querySelector(".side-menu");
  if (sideMenu && sideMenu.classList.contains("active")) {
    sideMenu.classList.remove("active");
    document.body.classList.remove("modal-open");
    document.body.style.overflow = ""; // Reset overflow
  }
}
